esim.source:
---
import SiteNav from '../components/SiteNav.astro';
import BlogLayout from '../layouts/BlogLayout.astro';
import SocialLinks from '../components/SocialLinks.astro';
import AffiliateDisclosure from '../components/AffiliateDisclosure.astro';
import ContentDisclaimer from '../components/ContentDisclaimer.astro';
import AffiliateRecommendations from '../components/AffiliateRecommendations.astro';
import { esimAffiliateUrls, esimRecommendations } from '../data/esim-recommendations';

const JOYTEL_LINK = esimAffiliateUrls.joytelCatalog;
const KKDAY_LINK = esimAffiliateUrls.kkdayVietnam;
const esimFaqs = [
  {
    question: 'eSIM 和實體 SIM、WiFi 機差在哪？',
    answer: 'eSIM 不用換實體卡，出發前掃描 QR Code 安裝，落地後切換行動數據即可使用；實體 SIM 需要換卡；WiFi 機適合多人共用，但需要租還與充電。',
  },
  {
    question: '一支手機可以同時用原本門號和 eSIM 嗎？',
    answer: '多數近年的雙 SIM 手機可以保留原本門號接電話或簡訊，並把 eSIM 設為行動數據；出發前仍要確認自己的機型支援 eSIM。',
  },
  {
    question: 'eSIM 裝了卻沒網路怎麼辦？',
    answer: '先確認 eSIM 已啟用、行動數據已切到 eSIM，並依業者指示檢查數據漫遊與 APN。若仍無法上網，再依序排查安裝、網路與裝置設定。',
  },
];
const esimStructuredData = {
  '@context': 'https://schema.org',
  '@type': 'FAQPage',
  '@id': 'https://comebacktraveler.com/esim#faq',
  mainEntity: esimFaqs.map(({ question, answer }) => ({
    '@type': 'Question',
    name: question,
    acceptedAnswer: { '@type': 'Answer', text: answer },
  })),
};

const brands = [
  {
    name: 'JOYTEL',
    badges: [{ label: '台灣品牌', cls: 'badge-tw' }, { label: '首推', cls: 'badge-rec' }],
    coverage: '日、韓、東南亞、歐洲、美加',
    priceNote: '原生/漫遊皆有',
    line: '依商品分原生／漫遊',
    lineNote: '本頁三電信方案為漫遊',
    hotspot: true,
    support: true,
    supportNote: 'LINE 全年無休',
    forWho: '台灣旅客、注重速度與客服',
    featured: true,
    tags: 'japan korea sea europe',
  },
  {
    name: 'DJB',
    badges: [{ label: '聲量 No.1', cls: 'badge-rec' }],
    coverage: '全球 90+ 國',
    priceNote: '暢日卡PLUS',
    line: '漫遊',
    lineNote: '多國電信合作',
    hotspot: true,
    support: true,
    supportNote: 'LINE 24hr',
    forWho: '重度上網、商務人士',
    featured: false,
    tags: 'japan korea sea europe',
  },
  {
    name: 'Klook',
    badges: [{ label: '平台型', cls: 'badge-platform' }],
    coverage: '日、韓、東南亞、澳洲等',
    priceNote: '吃到飽不降速',
    line: '漫遊',
    lineNote: '',
    hotspot: true,
    hotspotNote: '可分享',
    support: false,
    supportNote: '英文為主',
    forWho: '已用 Klook 訂行程者',
    featured: false,
    tags: 'japan korea sea',
  },
  {
    name: 'KKday',
    url: KKDAY_LINK,
    badges: [{ label: '平台型', cls: 'badge-platform' }],
    coverage: '日、韓、東南亞等',
    priceNote: '含/不含門號',
    line: '漫遊',
    lineNote: '',
    hotspot: true,
    support: false,
    supportNote: '英文為主',
    forWho: '需要當地門號接簡訊者',
    featured: false,
    tags: 'japan korea',
  },
  {
    name: 'WaySim 威訊',
    badges: [{ label: 'CP值高', cls: 'badge-cp' }],
    coverage: '日本、韓國等',
    priceNote: 'SK/Softbank 原生',
    line: '原生線路',
    lineNote: '5G 支援',
    hotspot: true,
    support: true,
    supportNote: 'LINE 客服',
    forWho: '日韓常客、預算有限者',
    featured: false,
    tags: 'japan korea',
  },
  {
    name: 'Airalo',
    badges: [{ label: '國際品牌', cls: 'badge-intl' }],
    coverage: '全球 190+ 國',
    priceNote: '依方案不同',
    line: '漫遊',
    lineNote: '',
    hotspot: false,
    hotspotNote: '部分方案不支援',
    support: false,
    supportNote: '英文介面',
    forWho: '多國旅行、英文使用者',
    featured: false,
    tags: 'europe',
  },
];
---

<BlogLayout
  title="出國 eSIM 怎麼選？住越南 10 年的台灣人幫你整理好了 | 重來的旅人"
  description="整理 6 家 eSIM 品牌完整比較表，以台灣旅客常去的日本、韓國、東南亞為主，5 分鐘做決定，不用再 Google 到天亮。"
  keywords="eSIM推薦,出國上網,JOYTEL,日本eSIM,韓國eSIM,東南亞eSIM,eSIM比較,台灣eSIM"
  ogImage="/esim-cover.jpg"
>
  <script slot="head" is:inline type="application/ld+json" set:html={JSON.stringify(esimStructuredData)} />
  <link
    slot="head"
    rel="preconnect"
    href="https://fonts.googleapis.com"
  />
  <link
    slot="head"
    href="https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;600;900&family=Noto+Sans+TC:wght@400;500&display=swap"
    rel="stylesheet"
  />

  <div class="esim-root">
    <!-- Site Header -->
    <SiteNav current="esim" />

    <!-- Hero -->
    <div class="hero">
      <div class="category-tag">出國上網 · eSIM 攻略</div>
      <h1>出國 eSIM 怎麼選？<br />住了越南 10 年的台灣人<br />幫你整理好了</h1>
      <p class="subtitle">
        前幾個月回越南辦事，才發現自己又在機場角落蹲著換卡 😅<br />
        住了 10 年的地方，還是搞得一頭霧水。<br />
        JOYTEL？DJB？Klook？Airalo？<br />
        每一家都說自己最好，但哪家適合你？<br /><br />
        身為在越南生活超過 10 年、踩過無數坑的過來人，
        我花了幾天把市場上最常見的 6 家整理成一張表——
        希望讓你 5 分鐘做決定，不用再 Google 到天亮。
      </p>
      <div class="meta">
        <div class="author-dot">旅</div>
        <div class="meta-info">
          <span class="meta-author">重來的旅人</span>
          <span>2026 年 4 月 · 越南住了 10 年、現在重新出發的中年男人</span>
        </div>
      </div>
    </div>

    <!-- Article -->
    <article class="article">

      <ContentDisclaimer />

      <section class="tip-box" aria-labelledby="esim-quick-answer">
        <div id="esim-quick-answer" class="tip-title">先說結論：出國 eSIM 怎麼選？</div>
        <p class="tip-body"><strong>手機支援 eSIM、想在落地就能上網並保留原門號的人，優先選 eSIM。</strong>先確認手機支援、目的地、天數、是否需要分享網路與客服語言；若多人共用再考慮 WiFi 機，手機不支援 eSIM 才考慮實體 SIM。</p>
        <p class="tip-body" style="margin-bottom:0;">需要進一步判斷時，可先看 <a href="/esim-quiz" style="color:var(--accent);font-weight:600;">30 秒上網方案測驗</a>，或遇到安裝問題直接看 <a href="/esim/troubleshoot" style="color:var(--accent);font-weight:600;">eSIM 設定排解</a>。</p>
      </section>

      <AffiliateDisclosure />
      <AffiliateRecommendations
        id="esim-quick-decision"
        heading="30 秒選出適合你的 eSIM"
        intro="先看你要去哪裡，再選想查看的品牌。手機已確認支援 eSIM，再往下挑就好。"
        article="/esim"
        placement="esim_quick_decision"
        recommendations={esimRecommendations}
      />

      <div class="story-box">
        <strong>先說說我自己</strong>——我不是旅遊達人，也不是網紅。<br />
        我是一個在越南工廠當副總、養蝦失敗、跑過 Uber、
        後來重新出發的中年台灣男人。<br /><br />
        正因為走過這些，我更知道：出門在外，手機沒網路，
        比什麼都讓人慌。這篇文章沒有業配口吻，
        只有一個過來人想告訴你的真心話。
      </div>

      <div style="border:1.5px solid var(--accent);border-radius:10px;padding:20px 24px;margin:8px 0 8px;background:#fef9f5;">
        <div style="font-family:var(--serif);font-weight:700;font-size:17px;margin-bottom:6px;">懶得看整張表？先做個 30 秒測驗</div>
        <p style="font-size:14.5px;color:var(--ink-light);margin:0 0 12px;line-height:1.7;">回答 4 個問題（去哪、待幾天、幾人、最在意什麼），我直接幫你判斷該用 eSIM、WiFi 機還是當地 SIM，eSIM 還會推薦對應品牌。</p>
        <a href="/esim-quiz" style="color:var(--accent);font-weight:600;text-decoration:none;">→ 開始 eSIM 決策樹測驗</a>
      </div>

      <h2>eSIM 是什麼？為什麼要用？</h2>
      <p>
        以前出國，一落地要拿出針來戳 SIM 卡槽、換卡、還要擔心台灣的號碼收不到訊息。
        當年我剛到越南，語言不通又被宰客，連怎麼上網都搞不清楚，走了很多冤枉路。
      </p>
      <p>
        現在有 eSIM，<strong>出發前在手機裡掃個 QR Code，落地直接開網路</strong>，
        連換卡這個動作都省了。對於帶家人出遊、或是像我這種不想麻煩的人，
        真的是差很多。
      </p>

      <div class="tip-box">
        <div class="tip-title">eSIM 使用前提</div>
        <p class="tip-body">
          iPhone XS 以後、多數 2019 年後的 Android 旗艦都支援 eSIM。
          使用前建議先到手機「設定 → 行動服務」確認是否有「新增行動方案」選項。
        </p>
      </div>

      <h2>六家 eSIM 品牌完整比較</h2>
      <p>
        以下是我整理的主要品牌比較，以<strong>台灣旅客最常去的日本、韓國、東南亞</strong>為主要參考方向。
        價格與方案以官方頁面為準，購買前請依自己的旅遊天數確認。
      </p>

      <!-- Table -->
      <div class="table-section">
        <div class="table-label">品牌比較表 · 2026 年整理</div>
        <div class="filter-bar" role="group" aria-label="依地區篩選">
          <button class="filter-btn active" data-tag="all">全部</button>
          <button class="filter-btn" data-tag="japan">日本</button>
          <button class="filter-btn" data-tag="korea">韓國</button>
          <button class="filter-btn" data-tag="sea">東南亞</button>
          <button class="filter-btn" data-tag="europe">歐洲</button>
        </div>
        <div class="table-wrap">
          <table>
            <thead>
              <tr>
                <th>品牌</th>
                <th>覆蓋地區</th>
                <th>價格與方案</th>
                <th>線路</th>
                <th>熱點分享</th>
                <th>中文客服</th>
                <th>適合誰</th>
              </tr>
            </thead>
            <tbody id="esim-tbody">
              {brands.map((b) => (
                <tr class={b.featured ? 'featured' : ''} data-tags={b.tags}>
                  <td>
                    <div class="brand-name">
                      {b.url
                        ? <a href={b.url} target="_blank" rel="sponsored noopener noreferrer">{b.name}</a>
                        : b.name}
                    </div>
                    {b.badges.map((badge) => (
                      <span class={`badge ${badge.cls}`}>{badge.label}</span>
                    ))}
                  </td>
                  <td>{b.coverage}</td>
                  <td>
                    以官方頁面為準
                    {b.priceNote && <div class="cell-note">{b.priceNote}</div>}
                  </td>
                  <td>
                    {b.line}
                    {b.lineNote && <div class="cell-note">{b.lineNote}</div>}
                  </td>
                  <td>
                    {b.hotspot
                      ? <span class="check">✓</span>
                      : <span class="cross">✗</span>}
                    {b.hotspotNote && <div class="cell-note">{b.hotspotNote}</div>}
                  </td>
                  <td>
                    {b.support
                      ? <span class="check">✓</span>
                      : <span class="cross">✗</span>}
                    {b.supportNote && <div class="cell-note">{b.supportNote}</div>}
                  </td>
                  <td>{b.forWho}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        <p class="table-note">※ 價格與方案以官方頁面為準。</p>
      </div>

      <h2>為什麼這篇推薦 JOYTEL？</h2>
      <p>
        理由不在於它最便宜——
        <strong>而是它公告的 LINE 中文客服為全年無休、真人對應</strong>。
      </p>
      <p>
        出國旅行最怕的就是遇到問題找不到人。
        如果 eSIM 開不了、訊號有問題，
        多數人需要的不是等 email 回覆，是馬上有人能用中文講清楚怎麼處理。
      </p>
      <p>
        另外，JOYTEL 日本商品有原生與漫遊等不同方案。
        <strong>上方的日本三電信 eSIM 是漫遊線路</strong>，別把「使用當地電信」直接當成「原生線路」；
        購買前仍要看清楚該商品的線路與限制。
      </p>

      <div class="story-box">
        「這篇不是替任何品牌背書。<br>
        本站的比較表都是依各品牌官方公告的線路類型、客服管道與方案資訊整理，<br>
        立場只有一個：幫帶著家人出門的台灣旅客，少在機場慌亂換卡。」
      </div>

      <!-- CTA -->
      <div class="cta-box">
        <p>還想多了解 JOYTEL？<br />先看線路、客服與選購重點，再決定是否適合這趟旅行。</p>
        <a class="cta-btn" href={JOYTEL_LINK || '/esim/joytel'} target={JOYTEL_LINK ? '_blank' : undefined} rel={JOYTEL_LINK ? 'sponsored noopener noreferrer' : undefined}>
          {JOYTEL_LINK ? '前往 JOYTEL 查看方案' : '看 JOYTEL 選購重點'} →
        </a>
        {JOYTEL_LINK && <p class="cta-label">※ 本文含聯盟行銷連結，點擊後購買我會獲得少量佣金，不影響你的價格</p>}
      </div>

      <h3>去越南，可以看 KKday 的單國方案</h3>
      <p>
        下方連結是 KKday 的越南 eSIM 商品，適合只去越南的行程。是否含門號、能否通話與收簡訊，請依所選方案的商品說明確認。
      </p>
      <p>
        如果是為了註冊當地 App 或收 OTP 驗證碼，不能只看到「含門號」就認為能用；這個商品的注意事項列明不支援接收當地 App 驗證簡訊。
      </p>
      <p>
        <a href={KKDAY_LINK} target="_blank" rel="sponsored noopener noreferrer" style="color:var(--accent);font-weight:500;">前往 KKday 查看越南 eSIM 方案 →</a>
      </p>
      <p class="table-note">※ 本段為聯盟連結，點擊購買我會獲得少量佣金，不影響你的價格</p>

      <div class="tip-box" style="margin:48px 0 0;">
        <div class="tip-title">eSIM 買了，不知道怎麼安裝？</div>
        <p class="tip-body">
          iPhone 掃 QR Code 在哪裡找、三星要去哪個設定頁——各廠牌路徑不一樣，看這篇就清楚了：<br>
          <a href="/esim/install" style="color:var(--accent);font-weight:500;">→ eSIM 安裝圖解教學（iPhone + Android）</a>
        </p>
      </div>

      <div class="tip-box" style="margin:24px 0 0;">
        <div class="tip-title">延伸閱讀</div>
        <p class="tip-body">
          想看更多依目的地或情境寫的 eSIM 文章：<br>
          <a href="/esim/china" style="color:var(--accent);font-weight:500;">→ 中國 eSIM 怎麼挑（含翻牆與線路差異）</a><br>
          <a href="/esim/joytel" style="color:var(--accent);font-weight:500;">→ JOYTEL eSIM 深度介紹（日本／韓國／東南亞）</a><br>
          <a href="/esim/troubleshoot" style="color:var(--accent);font-weight:500;">→ eSIM 收不到訊號／無法上網？排錯流程</a>
        </p>
      </div>

      <h2 id="esim-buying-checklist" tabindex="-1">挑選 eSIM 的三個重點</h2>
      <p>多國／跨洲行程先列出每一站與停留天數，核對方案是否全部涵蓋、有效期是否足夠、流量是共用或每日重置，再比較區域／全球方案與分國購買的總價。</p>

      <h3>1. 原生線路 vs 漫遊線路</h3>
      <p>
        <strong>原生線路</strong>：eSIM 直接接入當地電信（如日本 Docomo），速度快、延遲低，
        但方案選擇相對少。
        <strong>漫遊線路</strong>：透過台灣電信商轉接，選擇多、有時更便宜，
        但 PING 值較高（玩手遊可能有感）。一般旅遊兩者差異不大。
      </p>

      <h3>2. 吃到飽 vs 限量流量</h3>
      <p>
        一天滑手機、看地圖、傳 LINE，大約消耗 1–2 GB。
        如果你會開熱點給家人用，或是會拍 Reels 邊上傳，建議選吃到飽，
        省得旅途中一直看剩餘流量。
      </p>

      <h3>3. 購買時間</h3>
      <p>
        eSIM 可以提前購買，但是否能提前安裝、以及何時開始計算使用天數，會依不同商品而異。有些方案在啟用後開始計算，有些則在抵達目的地並連上當地網路後開始計算。購買後請先確認該方案的啟用與計日規則，再掃描或啟用 eSIM，避免提早消耗有效期。
      </p>

      <div class="tip-box">
        <div class="tip-title">老實說</div>
        <p class="tip-body">
          如果你英文沒問題、又常跑多國，Airalo 或 Klook 也是合理選擇。
          但若你希望遇到問題能立刻接到中文人工客服，
          就選有 LINE 客服的台灣品牌，心裡比較踏實。
        </p>
      </div>

      <h2>eSIM 常見問題</h2>
      <p><strong>Q：eSIM 和實體 SIM、WiFi 機差在哪？</strong><br>
        eSIM 不用換卡、不用帶針，掃 QR Code 就能裝，落地切換即用；WiFi 機要租還、要充電、多人共用一台。
        三種方案完整比較看
        <a href="/esim/overseas-internet-guide" style="color:var(--accent);">出國上網懶人包</a>。</p>
      <p><strong>Q：一支手機可以同時用原本門號和 eSIM 嗎？</strong><br>
        可以。多數近年的 iPhone / Android 支援雙 SIM，原門號保留接電話、eSIM 走數據，
        前提是手機支援 eSIM（舊機型請先確認）。</p>
      <p><strong>Q：要去中國大陸，這些 eSIM 能用嗎？</strong><br>
        大陸有防火長城，要選「免翻牆」的大陸專用方案，一般日韓卡不適用。看
        <a href="/esim/china" style="color:var(--accent);">中國大陸 eSIM 怎麼挑</a>。</p>
      <p><strong>Q：裝了之後沒網路怎麼辦？</strong><br>
        9 成是設定問題（APN、行動數據切換），先看
        <a href="/esim/troubleshoot" style="color:var(--accent);">eSIM 設定失敗 10 個常見問題</a>。</p>

      <h2>最後</h2>
      <p>
        人生有些事，你只有走過了才能告訴別人怎麼走。
        網路選擇、行前準備、旅途中的大小問題——這些細節，
        決定了你出門是放鬆還是焦慮。
      </p>
      <p>
        我花了前半生做了很多衝動的決定，現在希望能做一些真正有用的事。
        如果這篇文章幫你省了 10 分鐘的 Google，就已經值了。
      </p>
      <p>有問題歡迎在社群上找我，IG、FB、YouTube 我看到都會回。</p>

      <SocialLinks
        heading="追蹤我｜Follow Me"
        subheading="eSIM 選購整理更新、出國上網筆記與踩坑提醒，會在 IG、FB、YouTube 同步分享"
      />


    </article>

    <footer class="site-footer">
      <strong>重來的旅人</strong> · 把踩過的坑，變成你的攻略<br />
      <span>自媒體行銷 · 越南生活 10 年 · 現在重新出發</span>
      <div style="margin-top:12px;"><a href="/privacy" style="color:var(--accent);text-decoration:none;font-size:13px;">隱私權政策</a></div>
    </footer>
  </div>
</BlogLayout>

<script>
  // Filter buttons
  const btns = document.querySelectorAll<HTMLButtonElement>('.filter-btn');
  const rows = document.querySelectorAll<HTMLTableRowElement>('#esim-tbody tr');

  btns.forEach((btn) => {
    btn.addEventListener('click', () => {
      const tag = btn.dataset.tag ?? 'all';
      btns.forEach((b) => b.classList.remove('active'));
      btn.classList.add('active');
      rows.forEach((row) => {
        const tags = row.dataset.tags ?? '';
        row.style.display = (tag === 'all' || tags.includes(tag)) ? '' : 'none';
      });
    });
  });
</script>

<style>
  #esim-buying-checklist { scroll-margin-top: 96px; }

  .esim-root {
    --ink: #1a1208;
    --ink-light: #4a3f2f;
    --paper: #faf8f3;
    --paper-warm: #f2ede0;
    --accent: #c0392b;
    --gold: #b8860b;
    --border: #d4c9b0;
    --serif: 'Noto Serif TC', serif;
    --sans: 'Noto Sans TC', sans-serif;

    background: var(--paper);
    color: var(--ink);
    font-family: var(--sans);
    line-height: 1.8;
    font-size: 17px;
    min-height: 100vh;
  }

  /* Header */
  .site-header {
    border-bottom: 2px solid var(--ink);
    padding: 18px 0;
    text-align: center;
    background: var(--paper);
    position: sticky;
    top: 0;
    z-index: 100;
  }
  .site-name {
    font-family: var(--serif);
    font-weight: 900;
    font-size: 20px;
    letter-spacing: 0.12em;
    color: var(--ink);
  }
  .site-name span { color: var(--accent); }

  /* Hero */
  .hero {
    max-width: 740px;
    margin: 60px auto 0;
    padding: 0 24px;
  }
  .category-tag {
    font-family: var(--sans);
    font-size: 12px;
    font-weight: 500;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    color: var(--accent);
    border-left: 3px solid var(--accent);
    padding-left: 10px;
    margin-bottom: 20px;
  }
  h1 {
    font-family: var(--serif);
    font-weight: 900;
    font-size: clamp(28px, 5vw, 44px);
    line-height: 1.35;
    color: var(--ink);
    margin-bottom: 20px;
    letter-spacing: 0.02em;
  }
  .subtitle {
    font-size: 17px;
    color: var(--ink-light);
    margin-bottom: 32px;
    line-height: 1.7;
  }
  .meta {
    display: flex;
    align-items: center;
    gap: 20px;
    padding: 16px 0;
    border-top: 1px solid var(--border);
    border-bottom: 1px solid var(--border);
    margin-bottom: 48px;
    font-size: 13px;
    color: var(--ink-light);
  }
  .author-dot {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    background: var(--ink);
    color: var(--paper);
    font-family: var(--serif);
    font-weight: 900;
    font-size: 15px;
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }
  .meta-info { display: flex; flex-direction: column; gap: 2px; }
  .meta-author { font-weight: 500; font-size: 14px; color: var(--ink); }

  /* Article */
  .article {
    max-width: 740px;
    margin: 0 auto;
    padding: 0 24px 80px;
  }
  .article p { margin-bottom: 1.4em; color: var(--ink); }

  h2 {
    font-family: var(--serif);
    font-weight: 900;
    font-size: 26px;
    margin: 52px 0 16px;
    color: var(--ink);
    position: relative;
    padding-left: 16px;
  }
  h2::before {
    content: '';
    position: absolute;
    left: 0;
    top: 4px;
    width: 4px;
    height: 80%;
    background: var(--accent);
    border-radius: 2px;
  }
  h3 {
    font-family: var(--serif);
    font-weight: 600;
    font-size: 19px;
    margin: 32px 0 10px;
    color: var(--ink);
  }

  /* Story box */
  .story-box {
    background: var(--paper-warm);
    border-left: 4px solid var(--accent);
    padding: 24px 28px;
    margin: 40px 0;
    border-radius: 0 6px 6px 0;
    font-family: var(--serif);
    font-size: 16px;
    color: var(--ink-light);
    line-height: 1.9;
  }
  .story-box strong { color: var(--ink); font-weight: 600; }

  /* Tip box */
  .tip-box {
    border: 1.5px solid var(--border);
    border-radius: 6px;
    padding: 20px 24px;
    margin: 32px 0;
    background: var(--paper);
  }
  .tip-title {
    font-weight: 500;
    font-size: 13px;
    letter-spacing: 0.1em;
    color: var(--gold);
    text-transform: uppercase;
    margin-bottom: 8px;
    font-family: var(--sans);
  }
  .tip-body { margin: 0; font-size: 14px; color: var(--ink); }

  /* Table */
  .table-section { margin: 48px 0; }
  .table-label {
    font-size: 11px;
    font-weight: 500;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    color: var(--gold);
    margin-bottom: 12px;
  }
  .filter-bar {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
    margin-bottom: 16px;
  }
  .filter-btn {
    font-size: 13px;
    padding: 6px 14px;
    border-radius: 20px;
    border: 1px solid var(--border);
    background: var(--paper);
    color: var(--ink-light);
    cursor: pointer;
    transition: all 0.15s;
    font-family: var(--sans);
  }
  .filter-btn.active {
    background: var(--ink);
    color: var(--paper);
    border-color: var(--ink);
  }
  .table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; }
  table {
    width: 100%;
    border-collapse: collapse;
    font-size: 13.5px;
    min-width: 620px;
  }
  thead tr { background: var(--ink); }
  th {
    padding: 12px 14px;
    text-align: left;
    font-weight: 500;
    font-size: 11.5px;
    letter-spacing: 0.08em;
    color: var(--paper-warm);
    white-space: nowrap;
    font-family: var(--sans);
  }
  td {
    padding: 13px 14px;
    border-bottom: 1px solid var(--border);
    vertical-align: top;
    color: var(--ink);
    line-height: 1.5;
  }
  tr.featured td { background: #fef9f0; }
  tr:hover td { background: #f5f1e8; }
  tr.featured:hover td { background: #fef3e0; }
  .brand-name { font-weight: 500; font-family: var(--serif); font-size: 15px; }
  .badge {
    display: inline-block;
    font-size: 10px;
    padding: 2px 7px;
    border-radius: 10px;
    margin-top: 4px;
    font-family: var(--sans);
  }
  .badge-rec  { background: #fdebd0; color: #a04000; }
  .badge-tw   { background: #d5e8d4; color: #27611b; }
  .badge-platform { background: #e8d5f5; color: #5b2c8d; }
  .badge-intl { background: #d6eaf8; color: #1a5276; }
  .badge-cp   { background: #d5e8f5; color: #154360; }
  .check { color: #27ae60; font-weight: 600; }
  .cross { color: #c0392b; }
  .cell-note { font-size: 11px; color: var(--ink-light); margin-top: 2px; }
  .table-note { font-size: 12px; color: #888; margin-top: 10px; }

  /* CTA */
  .cta-box {
    background: var(--ink);
    color: var(--paper);
    padding: 32px 36px;
    border-radius: 8px;
    margin: 48px 0;
    text-align: center;
  }
  .cta-box p { color: #f2ede0; margin-bottom: 20px; font-size: 16px; }
  .cta-btn {
    display: inline-block;
    background: var(--accent);
    color: #fff;
    font-family: var(--serif);
    font-weight: 600;
    font-size: 16px;
    padding: 14px 36px;
    border-radius: 4px;
    text-decoration: none;
    letter-spacing: 0.04em;
    transition: background 0.2s;
  }
  .cta-btn:hover { background: #a93226; }
  .cta-label { font-size: 11px; color: #888; margin-top: 10px; font-family: var(--sans); }

  /* Footer */
  .site-footer {
    border-top: 2px solid var(--ink);
    padding: 40px 24px;
    text-align: center;
    font-size: 13px;
    color: var(--ink-light);
  }
  .site-footer strong { color: var(--ink); }
  .site-footer span { margin-top: 8px; display: inline-block; }

  /* Comment Form */
  .comment-section {
    margin-top: 60px;
    padding-top: 40px;
    border-top: 1px solid var(--border);
  }
  .comment-form {
    margin-top: 24px;
    display: flex;
    flex-direction: column;
    gap: 20px;
  }
  .hidden { display: none; }
  .form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px;
  }
  .form-group {
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .form-group label {
    font-size: 13px;
    font-weight: 500;
    color: var(--ink-light);
    letter-spacing: 0.04em;
  }
  .required { color: var(--accent); }
  .form-group input,
  .form-group textarea {
    font-family: var(--sans);
    font-size: 15px;
    padding: 10px 14px;
    border: 1.5px solid var(--border);
    border-radius: 4px;
    background: var(--paper);
    color: var(--ink);
    outline: none;
    transition: border-color 0.15s;
    resize: vertical;
  }
  .form-group input:focus,
  .form-group textarea:focus {
    border-color: var(--ink);
  }
  .form-group input::placeholder,
  .form-group textarea::placeholder {
    color: #b0a898;
  }
  .form-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
    flex-wrap: wrap;
  }
  .form-note {
    font-size: 12px;
    color: #999;
    margin: 0;
  }
  .submit-btn {
    font-family: var(--serif);
    font-weight: 600;
    font-size: 15px;
    padding: 12px 32px;
    background: var(--ink);
    color: var(--paper);
    border: none;
    border-radius: 4px;
    cursor: pointer;
    letter-spacing: 0.04em;
    transition: background 0.15s;
  }
  .submit-btn:hover { background: #2c1f0f; }
  .form-success {
    margin-top: 20px;
    padding: 18px 24px;
    background: #d5e8d4;
    border-radius: 4px;
    color: #27611b;
    font-size: 15px;
    font-weight: 500;
  }
  .form-success p { margin: 0; color: #27611b; }

  @media (max-width: 600px) {
    .hero { padding: 0 16px; }
    .article { padding: 0 16px 60px; }
    h1 { font-size: 28px; }
    .story-box { padding: 18px 20px; }
    .cta-box { padding: 24px 20px; }
    .form-row { grid-template-columns: 1fr; }
    .form-footer { flex-direction: column; align-items: flex-start; }
  }
</style>

esim-quiz.source:
---
import SiteNav from '../components/SiteNav.astro';
import SiteFooter from '../components/SiteFooter.astro';

const title = "eSIM 決策樹｜30 秒測出你的出國上網方案（日本・韓國・越南）";
const description = "不知道出國該用 eSIM、WiFi 機還是當地 SIM？回答 4 個問題，依人數、通話需求與天數，幫你選對日本、韓國、越南的上網方案，並推薦合適的 eSIM。中立工具，附完整文字版選購建議。";
const canonical = "https://comebacktraveler.com/esim-quiz";
---

<!DOCTYPE html>
<html lang="zh-Hant">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{title}</title>
  <meta name="description" content={description} />
  <meta name="keywords" content="eSIM 推薦,出國上網,WiFi機,當地SIM卡,日本eSIM,韓國eSIM,越南eSIM,上網方案選擇" />
  <link rel="canonical" href={canonical} />
  <meta property="og:type" content="article" />
  <meta property="og:title" content={title} />
  <meta property="og:description" content={description} />
  <meta property="og:url" content={canonical} />
  <meta property="og:locale" content="zh_TW" />
  <meta name="twitter:card" content="summary" />
  <meta name="twitter:title" content={title} />
  <meta name="twitter:description" content={description} />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;600;900&family=Noto+Sans+TC:wght@400;500&display=swap" rel="stylesheet">
  <script is:inline type="application/ld+json" set:html={JSON.stringify({
    "@context": "https://schema.org",
    "@type": "WebApplication",
    "name": "eSIM 決策樹｜出國上網方案測驗",
    "description": description,
    "url": canonical,
    "applicationCategory": "TravelApplication",
    "operatingSystem": "Web",
    "inLanguage": "zh-TW",
    "offers": { "@type": "Offer", "price": "0", "priceCurrency": "TWD" },
    "author": { "@type": "Person", "name": "重來的旅人", "url": "https://comebacktraveler.com/about" },
    "publisher": { "@type": "Organization", "name": "重來的旅人", "url": "https://comebacktraveler.com" }
  })} />
  <style>
    :root {
      --ink: #1a1208;
      --ink-light: #4a3f2f;
      --paper: #faf8f3;
      --paper-warm: #f2ede0;
      --accent: #c0392b;
      --gold: #b8860b;
      --border: #d4c9b0;
      --serif: 'Noto Serif TC', serif;
      --sans: 'Noto Sans TC', sans-serif;
    }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: var(--paper); color: var(--ink); font-family: var(--sans); line-height: 1.8; font-size: 17px; }

    .hero { max-width: 760px; margin: 56px auto 0; padding: 0 24px; }
    .category-tag { font-size: 12px; font-weight: 500; letter-spacing: 0.18em; text-transform: uppercase; color: var(--accent); border-left: 3px solid var(--accent); padding-left: 10px; margin-bottom: 20px; }
    h1 { font-family: var(--serif); font-weight: 900; font-size: clamp(27px, 4.5vw, 40px); line-height: 1.4; margin-bottom: 20px; }
    .subtitle { font-size: 17px; color: var(--ink-light); margin-bottom: 8px; line-height: 1.75; }

    .wrap { max-width: 760px; margin: 0 auto; padding: 0 24px 80px; }

    /* Quiz */
    .quiz { margin: 40px 0 0; }
    .q { border: 1.5px solid var(--border); border-radius: 10px; padding: 22px 24px; margin-bottom: 16px; background: var(--paper); }
    .q-head { display: flex; align-items: baseline; gap: 10px; margin-bottom: 14px; }
    .q-num { font-family: var(--serif); font-weight: 900; font-size: 14px; color: var(--accent); flex-shrink: 0; }
    .q-title { font-family: var(--serif); font-weight: 700; font-size: 18px; color: var(--ink); }
    .options { display: flex; flex-wrap: wrap; gap: 10px; }
    .opt {
      font-family: var(--sans); font-size: 15px; color: var(--ink);
      background: var(--paper-warm); border: 1.5px solid var(--border);
      border-radius: 999px; padding: 9px 18px; cursor: pointer;
      transition: background 0.15s, border-color 0.15s, color 0.15s;
    }
    .opt:hover { border-color: var(--accent); }
    .opt.selected { background: var(--accent); border-color: var(--accent); color: #fff; font-weight: 500; }

    .quiz-actions { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; margin-top: 24px; }
    .quiz-submit {
      font-family: var(--serif); font-weight: 600; font-size: 16px; color: #fff;
      background: var(--ink); border: none; border-radius: 6px; padding: 13px 32px; cursor: pointer;
      transition: background 0.15s, opacity 0.15s;
    }
    .quiz-submit:disabled { opacity: 0.4; cursor: not-allowed; }
    .quiz-submit:not(:disabled):hover { background: #2c1f0f; }
    .quiz-hint { font-size: 13px; color: var(--ink-light); }
    .quiz-reset { background: none; border: none; color: var(--accent); font-size: 14px; cursor: pointer; text-decoration: underline; padding: 0; font-family: var(--sans); }

    /* Result */
    .result { margin-top: 28px; }
    .result[hidden] { display: none; }
    .result-card { border: 2px solid var(--accent); border-radius: 12px; padding: 28px 30px; background: #fef9f5; }
    .result-label { font-size: 11px; font-weight: 500; letter-spacing: 0.16em; text-transform: uppercase; color: var(--accent); margin-bottom: 8px; }
    .result-title { font-family: var(--serif); font-weight: 900; font-size: 23px; color: var(--ink); margin-bottom: 12px; line-height: 1.4; }
    .result-summary { font-size: 16px; color: var(--ink-light); margin-bottom: 14px; }
    .result-note { font-size: 14px; color: var(--ink-light); background: var(--paper-warm); border-radius: 6px; padding: 12px 16px; margin-bottom: 16px; }
    .result-sub { font-size: 12px; font-weight: 600; letter-spacing: 0.08em; color: var(--gold); text-transform: uppercase; margin: 18px 0 8px; }
    .result-reading { list-style: none; padding: 0; margin: 0 0 18px; }
    .result-reading li { padding: 5px 0; }
    .result-reading a { color: var(--accent); text-decoration: none; font-size: 15px; font-weight: 500; }
    .result-reading a:hover { text-decoration: underline; }
    .result-cta {
      display: inline-block; background: var(--accent); color: #fff;
      font-family: var(--serif); font-weight: 600; font-size: 15px;
      padding: 12px 26px; border-radius: 6px; text-decoration: none;
    }
    .result-cta.alt { background: var(--ink); }
    .result-cta:hover { background: #a93226; }
    .result-cta.alt:hover { background: #2c1f0f; }
    .result-disclosure { font-size: 12px; color: var(--ink-light); margin-top: 10px; }
    .reset-row { margin-top: 16px; text-align: center; }

    /* Static prose */
    h2 { font-family: var(--serif); font-weight: 900; font-size: 24px; margin: 56px 0 16px; position: relative; padding-left: 16px; line-height: 1.4; }
    h2::before { content: ''; position: absolute; left: 0; top: 5px; width: 4px; height: 78%; background: var(--accent); border-radius: 2px; }
    h3 { font-family: var(--serif); font-weight: 700; font-size: 18px; margin: 28px 0 8px; }
    .prose p { margin-bottom: 1.3em; }
    .prose strong { color: var(--ink); }
    .prose a { color: var(--accent); }
    .plan-list { list-style: none; padding: 0; margin: 8px 0 1.3em; }
    .plan-list li { padding: 12px 0 12px 18px; border-left: 3px solid var(--border); margin-bottom: 10px; font-size: 15.5px; color: var(--ink-light); line-height: 1.75; }
    .plan-list li strong { color: var(--ink); }
    .internal-links { margin: 44px 0 0; padding-top: 28px; border-top: 1px solid var(--border); display: flex; gap: 20px; flex-wrap: wrap; }
    .internal-links a { color: var(--accent); text-decoration: none; font-size: 15px; font-weight: 500; }

    @media (max-width: 600px) { .hero, .wrap { padding: 0 18px; } }
  </style>
  <script is:inline async src="https://pagead2.googlesyndication.com/pagead/js/adsbygoogle.js?client=ca-pub-2666904599101446" crossorigin="anonymous"></script>
  <script is:inline async src="https://www.googletagmanager.com/gtag/js?id=G-XW4LBK8PYF"></script>
  <script is:inline>
    window.dataLayer = window.dataLayer || [];
    function gtag(){dataLayer.push(arguments);}
    gtag('js', new Date());
    gtag('config', 'G-XW4LBK8PYF');
  </script>
</head>
<body>

<SiteNav current="quiz" />

<div class="hero">
  <div class="category-tag">出國上網 · 互動工具</div>
  <h1>出國上網該用哪一種？<br>30 秒測出你的方案</h1>
  <p class="subtitle">
    eSIM、WiFi 機、還是當地 SIM 卡？回答下面 4 個問題，
    我會依你的人數、通話需求和天數，給你一個合理的建議——
    日本、韓國、越南都適用。這是中立工具，不會不管你怎麼選都推同一家。
  </p>
</div>

<div class="wrap">

  <!-- Interactive quiz -->
  <div class="quiz" id="quiz">
    <div class="q" data-q="dest">
      <div class="q-head"><span class="q-num">Q1</span><span class="q-title">你要去哪裡？</span></div>
      <div class="options">
        <button class="opt" data-val="jp">日本</button>
        <button class="opt" data-val="kr">韓國</button>
        <button class="opt" data-val="vn">越南</button>
      </div>
    </div>

    <div class="q" data-q="days">
      <div class="q-head"><span class="q-num">Q2</span><span class="q-title">待幾天？</span></div>
      <div class="options">
        <button class="opt" data-val="short">1–4 天</button>
        <button class="opt" data-val="mid">5–8 天</button>
        <button class="opt" data-val="long">9 天以上</button>
      </div>
    </div>

    <div class="q" data-q="people">
      <div class="q-head"><span class="q-num">Q3</span><span class="q-title">幾個人一起用這個網路？</span></div>
      <div class="options">
        <button class="opt" data-val="solo">只有我自己</button>
        <button class="opt" data-val="two">2 人共用</button>
        <button class="opt" data-val="group">3 人以上（家庭、團體）</button>
      </div>
    </div>

    <div class="q" data-q="care">
      <div class="q-head"><span class="q-num">Q4</span><span class="q-title">你最在意什麼？</span></div>
      <div class="options">
        <button class="opt" data-val="cheap">便宜就好</button>
        <button class="opt" data-val="stable">穩定不斷線、有中文客服</button>
        <button class="opt" data-val="call">要講電話或當地號碼</button>
      </div>
    </div>

    <div class="quiz-actions">
      <button class="quiz-submit" id="quiz-submit" disabled>看我的推薦 →</button>
      <span class="quiz-hint" id="quiz-hint">請先回答 4 個問題</span>
    </div>
  </div>

  <div class="result" id="result" hidden aria-live="polite"></div>

  <!-- Static text version (for SEO crawlers; not hidden behind interaction) -->
  <h2>不想點？這裡直接講選購邏輯</h2>
  <div class="prose">
    <p>
      上面的測驗只是把下面這套判斷濃縮成幾個按鈕。怕你嫌麻煩，我把完整邏輯用文字寫一遍——
      這也是我自己幫朋友決定上網方案時，腦袋裡跑的順序。
    </p>

    <h3>第一步：先決定「方案類型」</h3>
    <p>不是一開始就挑品牌，而是先確定你該用 eSIM、WiFi 機還是當地 SIM。判斷的優先順序是：<strong>人數 ＞ 通話需求 ＞ 天數</strong>。</p>
    <ul class="plan-list">
      <li><strong>3 人以上一起用 → WiFi 機（分享器）</strong>：一台機器多人分享，平均每人成本最低，全家或團體出遊最划算。缺點是要充電、要有人保管、隔天要記得帶出門。</li>
      <li><strong>1～2 人、不需要講電話 → eSIM</strong>：免換實體卡、免歸還、開機即用，單人或情侶/夫妻最方便。手機要支援 eSIM（iPhone XS 以後、近年的 Android 旗艦大多支援）。</li>
      <li><strong>需要講電話或當地門號 → 當地實體 SIM 卡</strong>：旅遊用 eSIM 多半只給「數據」，沒有當地號碼可以撥打電話。若你要打給當地飯店、餐廳訂位、或工作需要當地門號，落地辦一張實體 SIM 最直接。</li>
      <li><strong>只待 1～4 天、又只在意便宜 → eSIM 小流量方案</strong>：短天數不值得租 WiFi 機，買一個小流量的 eSIM 包就夠用，最省。</li>
    </ul>

    <h3>第二步：eSIM 要選哪一張？（依國家）</h3>
    <p>只有結果是 eSIM 時，才需要挑品牌。我的建議跟站上每一篇 eSIM 文章一致：</p>
    <ul class="plan-list">
      <li><strong>日本</strong>：在意穩定、要中文客服 → <strong>JOYTEL 日本原生線路</strong>；預算優先、已熟悉 eSIM → <strong>WaySim 威訊</strong>（原生線路、價格較親民）。完整比較見 <a href="/esim/japan">日本 eSIM 推薦</a>。</li>
      <li><strong>韓國</strong>：在意穩定、要中文客服 → <strong>JOYTEL 韓國原生線路</strong>；預算優先 → <strong>WaySim 威訊</strong>（適合日韓連著玩）。完整比較見 <a href="/esim/korea">韓國 eSIM 推薦</a>。</li>
      <li><strong>越南</strong>：優先選 <strong>Viettel 原生 eSIM</strong>（越南最大電信，覆蓋廣、訊號穩）。在台灣線上先買，通常比胡志明市新山一機場現場買便宜一截。細節見 <a href="/esim/saigon-airport-sim">胡志明機場 SIM 卡建議</a>。</li>
    </ul>

    <h3>還是不確定？先看這幾篇</h3>
    <p>
      如果你連 eSIM、WiFi 機、漫遊的差別都還沒搞懂，建議先讀
      <a href="/esim/overseas-internet-guide">出國上網三種方案完整比較</a>，再回來測一次會更有感。
      想看各品牌規格一次攤開，看 <a href="/esim">eSIM 品牌比較表</a>。
    </p>
  </div>

  <div class="internal-links">
    <a href="/esim">→ eSIM 品牌比較表</a>
    <a href="/esim/japan">→ 日本 eSIM 推薦</a>
    <a href="/esim/korea">→ 韓國 eSIM 推薦</a>
    <a href="/esim/saigon-airport-sim">→ 越南上網建議</a>
  </div>

</div>

<SiteFooter />

<script>
  // ── eSIM 決策樹：純前端、state 僅存記憶體，不使用 localStorage/sessionStorage ──
  const AFF = {
    joytelKr: 'https://onelink.one/s/LsI9l?sub_id=quiz',
    joytelVn: 'https://afflink.one/s/SNmCj?sub_id=quiz',
    viettelVn: 'https://linkgo.one/s/qG9cT?sub_id=quiz',
  };
  const AFF_META = {
    joytelKr: { product: 'JOYTEL 韓國 eSIM 方案', key: 'collection_joytel_korea_esim', merchant: 'joytel' },
    joytelVn: { product: 'JOYTEL 越南 Viettel eSIM 方案', key: 'collection_joytel_vietnam_esim', merchant: 'joytel' },
    viettelVn: { product: 'KKday 越南 Viettel 5G eSIM', key: 'kkday_vietnam_viettel_5g_esim', merchant: 'kkday' },
  };
  const READ = { jp: '/esim/japan', kr: '/esim/korea', vn: '/esim/saigon-airport-sim' };
  const GUIDE = { jp: '/japan-guide', kr: '/korea-guide', vn: '/vietnam-guide' };
  const OVERSEAS = '/esim/overseas-internet-guide';

  const L = {
    dest: { jp: '日本', kr: '韓國', vn: '越南' },
    days: { short: '1–4 天', mid: '5–8 天', long: '9 天以上' },
    people: { solo: '自己一個人', two: '兩人共用', group: '三人以上一起' },
    care: { cheap: '便宜就好', stable: '穩定不斷線、有中文客服', call: '要講電話或當地號碼' },
  };

  const answers = { dest: null, days: null, people: null, care: null };

  const quiz = document.getElementById('quiz');
  const submitBtn = document.getElementById('quiz-submit');
  const hint = document.getElementById('quiz-hint');
  const resultEl = document.getElementById('result');

  quiz.querySelectorAll('.q').forEach(function (group) {
    const key = group.getAttribute('data-q');
    group.querySelectorAll('.opt').forEach(function (btn) {
      btn.addEventListener('click', function () {
        answers[key] = btn.getAttribute('data-val');
        group.querySelectorAll('.opt').forEach(function (b) { b.classList.remove('selected'); });
        btn.classList.add('selected');
        refresh();
      });
    });
  });

  function allAnswered() {
    return answers.dest && answers.days && answers.people && answers.care;
  }
  function refresh() {
    const done = allAnswered();
    submitBtn.disabled = !done;
    hint.textContent = done ? '可以看結果了' : '請先回答 4 個問題';
  }

  function esc(s) { return String(s).replace(/[&<>"]/g, function (c) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]; }); }

  function brandFor(dest, care) {
    // care 在此只會是 cheap 或 stable（call 已在第一步分流到實體 SIM）
    const stable = care === 'stable';
    if (dest === 'jp') {
      return stable
        ? { name: 'JOYTEL 日本原生線路', reason: 'JOYTEL 走日本當地原生線路，速度穩、有中文 LINE 真人客服，第一次自助、怕斷線的人最安心。', cta: { href: READ.jp, label: '比較其他日本 eSIM 方案 →', aff: false } }
        : { name: 'WaySim 威訊（日本原生）', reason: '同樣是原生線路但價格較親民，適合預算優先、已經熟悉 eSIM 操作的人。我把它和 JOYTEL 的差異整理在日本 eSIM 推薦文裡。', cta: { href: READ.jp, label: '看 JOYTEL vs WaySim 完整比較 →', aff: false } };
    }
    if (dest === 'kr') {
      return stable
        ? { name: 'JOYTEL 韓國原生線路', reason: 'JOYTEL 走韓國原生線路，Naver Map 導航、中文 LINE 客服都到位，求穩的人選它。', cta: { href: AFF.joytelKr, label: '查看 JOYTEL 韓國方案 →', aff: true, metadata: AFF_META.joytelKr } }
        : { name: 'WaySim 威訊（韓國原生）', reason: '原生線路、價格較親民，若你打算日韓連著玩也方便。詳細差異看韓國 eSIM 推薦文。', cta: { href: READ.kr, label: '看 JOYTEL vs WaySim 完整比較 →', aff: false } };
    }
    // vn
    return stable
      ? { name: 'Viettel 原生 eSIM（JOYTEL）', reason: 'Viettel 是越南最大電信，覆蓋廣、訊號穩，胡志明、河內、峴港都不太需要擔心。要穩就選原生 Viettel。', cta: { href: AFF.joytelVn, label: '查看越南 Viettel 原生 eSIM →', aff: true, metadata: AFF_META.joytelVn } }
      : { name: 'Viettel 原生 eSIM（線上先買）', reason: '越南上網我一律優先看 Viettel。重點不是換品牌，而是「在台灣線上先買」通常比新山一機場現場買便宜一截。', cta: { href: AFF.viettelVn, label: '查看越南 Viettel 5G eSIM →', aff: true, metadata: AFF_META.viettelVn } };
  }

  function recommend(a) {
    const destL = L.dest[a.dest], daysL = L.days[a.days], peopleL = L.people[a.people], careL = L.care[a.care];
    const base = '你' + peopleL + '、去' + destL + daysL + '、最在意「' + careL + '」——';

    // 第一步：方案類型（人數 > 通話 > 天數）
    let plan;
    if (a.people === 'group') plan = 'wifi';
    else if (a.care === 'call') plan = 'sim';
    else plan = 'esim';

    if (plan === 'wifi') {
      return {
        title: '建議用 WiFi 機（分享器）',
        summary: base + '人多的時候，一台 WiFi 機分享給大家最划算，平均每人成本最低。',
        note: '小提醒：WiFi 機要充電、要有人保管，出門前記得帶。如果其中有人會單獨行動，那個人可以另外加一張 eSIM。',
        reading: [
          { href: OVERSEAS, label: '出國上網三種方案完整比較' },
          { href: GUIDE[a.dest], label: destL + '自由行攻略' },
        ],
        cta: null,
      };
    }
    if (plan === 'sim') {
      const reading = [{ href: a.dest === 'vn' ? READ.vn : OVERSEAS, label: a.dest === 'vn' ? '胡志明機場 SIM 卡建議' : '出國上網三種方案完整比較' }];
      return {
        title: '建議辦當地實體 SIM 卡',
        summary: base + '旅遊用 eSIM 多半只給數據、沒有當地號碼。你要講電話或需要當地門號，落地辦一張實體 SIM 最直接。',
        note: a.dest === 'vn'
          ? '越南的話，機場現場辦最快，但價格通常比線上貴；可參考下面那篇先比一下。'
          : '若你其實只是要上網、不一定要通話，回上面把 Q4 改成「穩定」或「便宜」，eSIM 會更方便。',
        reading: reading,
        cta: null,
      };
    }

    // eSIM
    const brand = brandFor(a.dest, a.care);
    const smallData = (a.days === 'short' && a.care === 'cheap');
    return {
      title: '建議用 eSIM — ' + brand.name,
      summary: base + brand.reason,
      note: smallData ? '你天數短又想省，買「小流量方案」就夠用，不用買大包流量。' : null,
      reading: [
        { href: READ[a.dest], label: destL + ' eSIM 推薦與比較' },
        { href: GUIDE[a.dest], label: destL + '自由行攻略' },
      ],
      cta: brand.cta,
    };
  }

  function render(r) {
    let html = '';
    html += '<div class="result-card">';
    html += '<div class="result-label">你的推薦</div>';
    html += '<h3 class="result-title">' + esc(r.title) + '</h3>';
    html += '<p class="result-summary">' + esc(r.summary) + '</p>';
    if (r.note) html += '<div class="result-note">' + esc(r.note) + '</div>';

    html += '<div class="result-sub">延伸閱讀</div><ul class="result-reading">';
    r.reading.forEach(function (item) {
      html += '<li><a href="' + esc(item.href) + '">' + esc(item.label) + ' →</a></li>';
    });
    html += '</ul>';

    if (r.cta) {
      const rel = r.cta.aff ? 'noopener sponsored' : 'noopener';
      const target = r.cta.aff ? ' target="_blank"' : '';
      const cls = r.cta.aff ? 'result-cta' : 'result-cta alt';
      let metadata = '';
      if (r.cta.aff && r.cta.metadata) {
        const item = r.cta.metadata;
        metadata = ' data-affiliate="affiliates_one" data-affiliate-category="esim" data-cta-position="quiz_result"' +
          ' data-affiliate-product="' + esc(item.product) + '" data-affiliate-product-key="' + esc(item.key) +
          '" data-affiliate-merchant="' + esc(item.merchant) + '"';
      }
      html += '<a class="' + cls + '" href="' + esc(r.cta.href) + '"' + target + ' rel="' + rel + '"' + metadata + '>' + esc(r.cta.label) + '</a>';
      if (r.cta.aff) html += '<p class="result-disclosure">本連結為聯盟連結，你透過它購買我會獲得少量分潤，但不影響你的價格。</p>';
    }

    html += '</div>';
    html += '<div class="reset-row"><button class="quiz-reset" id="quiz-reset">↻ 重新測驗</button></div>';
    resultEl.innerHTML = html;
    resultEl.hidden = false;

    document.getElementById('quiz-reset').addEventListener('click', resetQuiz);
    resultEl.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  function resetQuiz() {
    answers.dest = answers.days = answers.people = answers.care = null;
    quiz.querySelectorAll('.opt.selected').forEach(function (b) { b.classList.remove('selected'); });
    resultEl.hidden = true;
    resultEl.innerHTML = '';
    refresh();
    quiz.scrollIntoView({ behavior: 'smooth', block: 'start' });
  }

  submitBtn.addEventListener('click', function () {
    if (!allAnswered()) return;
    render(recommend(answers));
  });
</script>

</body>
</html>

esim/install.source:
---
import SiteNav from '../../components/SiteNav.astro';
import SiteFooter from '../../components/SiteFooter.astro';
import SocialLinks from '../../components/SocialLinks.astro';
import AffiliateDisclosure from '../../components/AffiliateDisclosure.astro';
import ContentDisclaimer from '../../components/ContentDisclaimer.astro';

const title = "eSIM 怎麼安裝？iPhone + Android 圖解教學｜重來的旅人";
const description = "第一次裝 eSIM 不知道從哪開始？iPhone 掃 QR Code、Android 三星/Pixel 步驟全圖解，5 分鐘搞定，附常見問題排解。";
const JOYTEL_LINK = 'https://linkgo.one/s/I6wBM';
---

<!DOCTYPE html>
<html lang="zh-Hant">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>{title}</title>
  <meta name="description" content={description} />
  <meta name="keywords" content="eSIM安裝,eSIM教學,iPhone eSIM,Android eSIM,三星eSIM,eSIM QR Code,JOYTEL安裝" />
  <link rel="canonical" href="https://comebacktraveler.com/esim/install" />
  <meta property="og:type" content="article" />
  <meta property="og:title" content={title} />
  <meta property="og:description" content={description} />
  <meta property="og:url" content="https://comebacktraveler.com/esim/install" />
  <meta property="og:locale" content="zh_TW" />
  <script is:inline type="application/ld+json" set:html={JSON.stringify({
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    "headline": title,
    "description": description,
    "url": "https://comebacktraveler.com/esim/install",
    "mainEntityOfPage": "https://comebacktraveler.com/esim/install",
    "inLanguage": "zh-TW",
    "datePublished": "2026-04-22",
    "dateModified": "2026-04-22",
    "author": { "@type": "Person", "name": "重來的旅人", "url": "https://comebacktraveler.com/about" },
    "publisher": { "@type": "Organization", "name": "重來的旅人", "url": "https://comebacktraveler.com" }
  })} />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Noto+Serif+TC:wght@400;600;900&family=Noto+Sans+TC:wght@400;500&display=swap" rel="stylesheet">
  <style>
    :root {
      --ink: #1a1208;
      --ink-light: #4a3f2f;
      --paper: #faf8f3;
      --paper-warm: #f2ede0;
      --accent: #c0392b;
      --gold: #b8860b;
      --border: #d4c9b0;
      --green: #1D9E75;
      --serif: 'Noto Serif TC', serif;
      --sans: 'Noto Sans TC', sans-serif;
    }
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { background: var(--paper); color: var(--ink); font-family: var(--sans); line-height: 1.8; font-size: 17px; }

    .site-header { border-bottom: 2px solid var(--ink); padding: 18px 0; text-align: center; background: var(--paper); position: sticky; top: 0; z-index: 100; }
    .site-name { font-family: var(--serif); font-weight: 900; font-size: 20px; letter-spacing: 0.12em; color: var(--ink); text-decoration: none; }
    .site-name span { color: var(--accent); }

    .hero { max-width: 740px; margin: 60px auto 0; padding: 0 24px; }
    .category-tag { font-size: 12px; font-weight: 500; letter-spacing: 0.18em; text-transform: uppercase; color: var(--accent); border-left: 3px solid var(--accent); padding-left: 10px; margin-bottom: 20px; }
    h1 { font-family: var(--serif); font-weight: 900; font-size: clamp(26px, 5vw, 42px); line-height: 1.35; margin-bottom: 20px; }
    .subtitle { font-size: 17px; color: var(--ink-light); margin-bottom: 32px; line-height: 1.7; }
    .meta { display: flex; align-items: center; gap: 20px; padding: 16px 0; border-top: 1px solid var(--border); border-bottom: 1px solid var(--border); margin-bottom: 48px; font-size: 13px; color: var(--ink-light); }
    .author-dot { width: 40px; height: 40px; border-radius: 50%; background: var(--ink); color: var(--paper); font-family: var(--serif); font-weight: 900; font-size: 15px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; }
    .meta-author { font-weight: 500; font-size: 14px; color: var(--ink); }

    .article { max-width: 740px; margin: 0 auto; padding: 0 24px 80px; }
    .article p { margin-bottom: 1.4em; }

    .story-box { background: var(--paper-warm); border-left: 4px solid var(--accent); padding: 24px 28px; margin: 40px 0; border-radius: 0 6px 6px 0; font-family: var(--serif); font-size: 16px; color: var(--ink-light); line-height: 1.9; }
    .story-box strong { color: var(--ink); font-weight: 600; }

    h2 { font-family: var(--serif); font-weight: 900; font-size: 26px; margin: 52px 0 16px; position: relative; padding-left: 16px; }
    h2::before { content: ''; position: absolute; left: 0; top: 4px; width: 4px; height: 80%; background: var(--accent); border-radius: 2px; }
    h3 { font-family: var(--serif); font-weight: 600; font-size: 20px; margin: 36px 0 12px; }

    /* OS Tab Switch */
    .os-tabs { display: flex; gap: 0; margin: 32px 0 0; border-bottom: 2px solid var(--border); }
    .os-tab { font-family: var(--serif); font-size: 16px; font-weight: 600; padding: 12px 28px; border: none; background: transparent; color: var(--ink-light); cursor: pointer; border-bottom: 3px solid transparent; margin-bottom: -2px; transition: color 0.15s, border-color 0.15s; }
    .os-tab.active { color: var(--accent); border-bottom-color: var(--accent); }
    .os-panel { display: none; padding: 32px 0 0; }
    .os-panel.active { display: block; }

    /* Step cards */
    .steps { list-style: none; padding: 0; margin: 24px 0; display: flex; flex-direction: column; gap: 16px; }
    .step { display: flex; gap: 16px; align-items: flex-start; }
    .step-num { width: 32px; height: 32px; border-radius: 50%; background: var(--ink); color: var(--paper); font-family: var(--serif); font-weight: 900; font-size: 14px; display: flex; align-items: center; justify-content: center; flex-shrink: 0; margin-top: 2px; }
    .step-body { flex: 1; }
    .step-title { font-family: var(--serif); font-weight: 600; font-size: 17px; margin-bottom: 4px; color: var(--ink); }
