    .step-path { display: inline-block; background: var(--paper-warm); border: 1px solid var(--border); border-radius: 4px; padding: 4px 10px; font-size: 13px; color: var(--ink); font-family: var(--sans); margin: 6px 0; letter-spacing: 0.02em; }

