    .related-card:hover { border-color: var(--accent); transform: translateY(-2px); }
    .related-label { font-size: 11px; color: var(--accent); letter-spacing: 0.14em; text-transform: uppercase; margin-bottom: 6px; font-family: var(--sans); }
    .related-title { font-family: var(--serif); font-weight: 600; font-size: 15px; color: var(--ink); line-height: 1.4; }

    /* CTA */
    .cta-box { background: var(--ink); color: var(--paper); padding: 32px 36px; border-radius: 8px; margin: 48px 0; text-align: center; }
    .cta-box p { color: #d4c9b0; margin-bottom: 20px; font-size: 16px; }
    .cta-btn { display: inline-block; background: var(--accent); color: #fff; font-family: var(--serif); font-weight: 600; font-size: 16px; padding: 14px 36px; border-radius: 4px; text-decoration: none; letter-spacing: 0.04em; transition: background 0.2s; }
    .cta-btn:hover { background: #a93226; }
    .cta-label { font-size: 11px; color: #666; margin-top: 10px; }

    footer { border-top: 2px solid var(--ink); padding: 40px 24px; text-align: center; font-size: 13px; color: var(--ink-light); }
    .footer-links { margin-top: 12px; display: flex; justify-content: center; gap: 24px; flex-wrap: wrap; }
    .footer-links a { color: var(--accent); text-decoration: none; font-size: 13px; }

    .comment-section { margin-top: 60px; padding-top: 40px; border-top: 1px solid var(--border); }
    .comment-form { margin-top: 24px; display: flex; flex-direction: column; gap: 20px; }
